from pathlib import Path

p = Path("index.html")
s = p.read_text(encoding="utf-8")

anchor = "const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];"
insert = "const snapshotDataCache={fixtures:new Map(),teams:new Map()};\n"
if s.count(anchor) != 1:
    raise SystemExit(f"state anchor count={s.count(anchor)}")
s = s.replace(anchor, insert + anchor, 1)

anchor2 = "function teamEbookPair(m){"
if s.count(anchor2) != 1:
    raise SystemExit(f"teamEbookPair anchor count={s.count(anchor2)}")

helpers = r'''function snapshotRunRef(){const meta=obj(state.currentRun?.meta),date=meta.date||$('#runDate')?.value||'',snapshotId=meta.data_snapshot_id||meta.snapshot_id||'';return {date,snapshotId}}
function snapshotNameKey(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function storedTeamEbookAvailable(m){const te=teamEbookPair(m);return Object.keys(obj(te.home)).length>0||Object.keys(obj(te.away)).length>0}
async function snapshotCachedJSON(path,cache){if(!cache.has(path)){const promise=getJSON(path).catch(e=>{cache.delete(path);throw e});cache.set(path,promise)}return cache.get(path)}
async function hydrateMatchSnapshot(m){if(storedTeamEbookAvailable(m)){m.__snapshotFallback={status:'not_needed',source:'RUN_TEAM_EBOOK'};return m.__snapshotFallback}const current=obj(m.__snapshotFallback);if(['loaded','missing','error','not_needed'].includes(current.status))return current;const {date,snapshotId}=snapshotRunRef();if(!date||!snapshotId){m.__snapshotFallback={status:'missing',reason:'NO_SNAPSHOT_REFERENCE'};return m.__snapshotFallback}m.__snapshotFallback={status:'loading',date,snapshotId};try{const root=`data/${date}/${snapshotId}/`,fixturePath=`${root}fixtures.json`,bundle=await snapshotCachedJSON(fixturePath,snapshotDataCache.fixtures);let row=arr(bundle.fixtures).find(x=>x?.fixture?.fixture_id&&x.fixture.fixture_id===m.fixture_id);if(!row){const hk=snapshotNameKey(m.home),ak=snapshotNameKey(m.away);row=arr(bundle.fixtures).find(x=>snapshotNameKey(x?.fixture?.home_team_name)===hk&&snapshotNameKey(x?.fixture?.away_team_name)===ak)}if(!row){m.__snapshotFallback={status:'missing',reason:'FIXTURE_NOT_IN_SNAPSHOT',date,snapshotId};return m.__snapshotFallback}const loadSide=async side=>{const info=obj(row[`${side}_team`]),ref=info.ref;if(!ref)return null;return snapshotCachedJSON(`${root}${ref}`,snapshotDataCache.teams)};const [home,away]=await Promise.all([loadSide('home'),loadSide('away')]);m.__snapshotFallback={status:'loaded',date,snapshotId,fixture:row.fixture||{},home,away,homeRef:row.home_team?.ref||null,awayRef:row.away_team?.ref||null};return m.__snapshotFallback}catch(e){m.__snapshotFallback={status:'error',date,snapshotId,reason:e.message||String(e)};return m.__snapshotFallback}}
function snapshotLineage(t){const l=obj(t?.feature_lineage),sources=arr(l.upstream_sources);return sources.length?sources.join(' · '):l.transport_layer||''}
function snapshotRecord(t,prefix){const f=obj(t?.feature_state),w=f[`${prefix}wins`],d=f[`${prefix}draws`],l=f[`${prefix}losses`],n=f[`${prefix}n`];return [present(n)?`N ${n}`:'',present(w)?`W ${w}`:'',present(d)?`D ${d}`:'',present(l)?`L ${l}`:''].filter(Boolean).join(' · ')}
function snapshotTeamBox(t,name,role){t=obj(t);if(!Object.keys(t).length)return `<div class="teambook-card panel"><div class="teambook-head"><div><h4>${show(name)}</h4><small>Snapshot Team Data</small></div><span class="chip yellow">NO TEAM FILE</span></div><div class="tb-empty">Für dieses Team besitzt der referenzierte Daily Snapshot keine verwendbare Team-Datei.</div></div>`;const f=obj(t.feature_state),st=obj(t.feature_status),cut=obj(t.feature_cutoff),rolePrefix=role==='HOME'?'home_':'away_',roleL5=`${rolePrefix}last5_cross_season_`,allL5='last5_all_competitions_',season='season_to_date_';const metrics=[tbMetric('xG L5',f.last5_cross_season_xg_for_avg,true),tbMetric('xGA L5',f.last5_cross_season_xg_against_avg,true),tbMetric('PPG L5',f.last5_cross_season_ppg),tbMetric('Features',st.n_features),tbMetric('Nulls',st.n_null_values),tbMetric('Rest',present(f.rest_days_all_competitions)?`${f.rest_days_all_competitions}d`:f.rest_days)].filter(Boolean).join('');const blocks=arr(st.blocks_present).join(' · ');const currentRecord=snapshotRecord(t,season),allRecord=snapshotRecord(t,allL5),roleRecord=snapshotRecord(t,roleL5);const gf=f.last5_cross_season_goals_for_avg,ga=f.last5_cross_season_goals_against_avg,shots=f.last5_cross_season_shots_for_avg,sot=f.last5_cross_season_shots_on_target_for_avg,roleShots=f[`${roleL5}shots_for_avg`],roleSot=f[`${roleL5}shots_on_target_for_avg`],fhgf=f.first_half_last5_cross_season_goals_for_avg,fhga=f.first_half_last5_cross_season_goals_against_avg,shgf=f.second_half_last5_cross_season_goals_for_avg,shga=f.second_half_last5_cross_season_goals_against_avg;return `<div class="teambook-card panel"><div class="teambook-head"><div><h4>${show(t.team_name||name)}</h4><small>${role} · Snapshot Team Data · PIT ${show(cut.cutoff_date||t.date)}</small></div><span class="chip blue">SNAPSHOT FALLBACK</span></div>${metrics?`<div class="tb-metrics">${metrics}</div>`:''}<div class="tb-lines">${tbLine('Current Season',currentRecord)}${tbLine('L5 All Competitions',allRecord)}${tbLine(`${role} L5`,roleRecord)}${tbLine('GF / GA L5',present(gf)||present(ga)?`${present(gf)?gf:'—'} / ${present(ga)?ga:'—'}`:'')}${tbLine('Shots / SOT L5',present(shots)||present(sot)?`${present(shots)?shots:'—'} / ${present(sot)?sot:'—'}`:'')}${tbLine(`${role} Shots / SOT L5`,present(roleShots)||present(roleSot)?`${present(roleShots)?roleShots:'—'} / ${present(roleSot)?roleSot:'—'}`:'')}${tbLine('1H GF / GA L5',present(fhgf)||present(fhga)?`${present(fhgf)?fhgf:'—'} / ${present(fhga)?fhga:'—'}`:'')}${tbLine('2H GF / GA L5',present(shgf)||present(shga)?`${present(shgf)?shgf:'—'} / ${present(shga)?shga:'—'}`:'')}${tbLine('Corners For / Against L5',present(f.last5_cross_season_corners_for_avg)||present(f.last5_cross_season_corners_against_avg)?`${show(f.last5_cross_season_corners_for_avg)} / ${show(f.last5_cross_season_corners_against_avg)}`:'')}${tbLine('Cards For / Against L5',present(f.last5_cross_season_total_cards_for_avg)||present(f.last5_cross_season_total_cards_against_avg)?`${show(f.last5_cross_season_total_cards_for_avg)} / ${show(f.last5_cross_season_total_cards_against_avg)}`:'')}${tbLine('H2H L5',present(f.h2h_last5_n)?`N ${f.h2h_last5_n} · W ${show(f.h2h_last5_wins)} · D ${show(f.h2h_last5_draws)} · L ${show(f.h2h_last5_losses)} · xG ${show(f.h2h_last5_xg_for_avg)}:${show(f.h2h_last5_xg_against_avg)}`:'')}${tbLine('Snapshot Blocks',blocks)}${tbLine('Feature Sources',snapshotLineage(t))}${tbLine('PIT Rule',cut.point_in_time_rule)}</div></div>`}
function renderTeamEbookSection(m,te){const stored=Object.keys(obj(te.home)).length>0||Object.keys(obj(te.away)).length>0,s=obj(m.__snapshotFallback);if(stored)return `<details><summary>Team E-Books</summary><div class="inside"><div class="detail-grid">${teamBox(te.home,m.home)}${teamBox(te.away,m.away)}</div></div></details>`;if(s.status==='loaded')return `<details open><summary>Team E-Books · Snapshot Fallback <span class="priority">DATA BASIS</span></summary><div class="inside"><div class="df-mode-note">Dieser Run speichert keine fertigen Team E-Books. Deshalb zeigt ECOBET hier die tatsächlich referenzierten Point-in-Time Team-Daten aus ${show(s.snapshotId)}. Diese Feature-Basis ist kein nachträglich erfundener normativer E-Book- oder SB-Status.</div><div class="detail-grid" style="margin-top:10px">${snapshotTeamBox(s.home,m.home,'HOME')}${snapshotTeamBox(s.away,m.away,'AWAY')}</div></div></details>`;if(s.status==='error')return `<details open><summary>Team E-Books · Snapshot Fallback</summary><div class="inside"><div class="error">Snapshot-Daten konnten nicht geladen werden: ${show(s.reason)}</div></div></details>`;if(s.status==='missing')return `<details open><summary>Team E-Books · Snapshot Fallback</summary><div class="inside"><div class="df-mode-note">Der Run enthält keine Team E-Books und für dieses Match konnte keine verwendbare Snapshot-Teamreferenz ermittelt werden (${show(s.reason)}).</div></div></details>`;return `<details open><summary>Team E-Books · Snapshot Fallback</summary><div class="inside"><div class="loading">Snapshot Team Data wird geladen …</div></div></details>`}
function renderSnapshotFabric(m){const s=obj(m.__snapshotFallback);if(s.status==='loaded'){const side=(t,label)=>{t=obj(t);const st=obj(t.feature_status);return `<div class="df-row"><div class="df-top"><div><span class="df-code">${label}</span><span class="sb-name">${show(t.team_name)}</span></div><span class="chip blue">SNAPSHOT BASIS</span></div><div class="df-status"><span class="chip">Features ${show(st.n_features)}</span><span class="chip">Null ${show(st.n_null_values)}</span></div><div class="df-evidence">${arr(st.blocks_present).length?`Blocks: ${arr(st.blocks_present).map(show).join(' · ')}`:'Keine Block-Metadaten gespeichert.'}</div></div>`};return `<div class="df-mode-note">Der gespeicherte Run enthält keine normative SB01–SB17 Map und keine DF01–DF16 Compatibility Map. Angezeigt wird deshalb ausschliesslich die vorhandene Snapshot-Datenbasis. Sie darf nicht als READINESS_AUTHORITY interpretiert werden.</div><div class="df-grid" style="margin-top:9px">${side(s.home,'HOME')}${side(s.away,'AWAY')}</div>`}if(s.status==='error')return `<div class="error">Snapshot Data Fabric Basis konnte nicht geladen werden: ${show(s.reason)}</div>`;if(s.status==='missing')return `<div class="df-mode-note">Keine SB/DF Statusmap im Run und keine verwendbare Snapshot-Datenbasis für dieses Match (${show(s.reason)}).</div>`;return `<div class="loading">Snapshot Data Fabric Basis wird geladen …</div>`}
'''
s = s.replace(anchor2, helpers + "\n" + anchor2, 1)

start = s.index("function renderDataFabric(m,fs){")
end = s.index("\nfunction candidateTable(m){", start)
new_render = r'''function renderDataFabric(m,fs){const current=renderSignalBlocks(m),legacy=renderLegacyDF(m,fs);if(current&&legacy)return `${current}<details class="df-compat"><summary>DF01–DF16 · Legacy Compatibility View</summary>${legacy}</details>`;if(current)return current;if(legacy)return `${isV17DataFabric()?'<div class="df-mode-note">Dieser gespeicherte v1.7+ Run enthält keine SB01–SB17-Struktur. Die vorhandenen DF01–DF16-Daten werden deshalb ausschliesslich als Legacy Compatibility View dargestellt.</div>':'<div class="df-mode-note">Dieser gespeicherte Run verwendet die historische DF01–DF16 Data-Fabric-Struktur.</div>'}${legacy}`;return renderSnapshotFabric(m)}'''
s = s[:start] + new_render + s[end:]

old_team = '<details><summary>Team E-Books</summary><div class="inside"><div class="detail-grid">${teamBox(te.home,m.home)}${teamBox(te.away,m.away)}</div></div></details>'
detail_start = s.index("function detailHTML(m){")
detail_end = s.index("\nfunction deepMetric", detail_start)
detail = s[detail_start:detail_end]
if detail.count(old_team) != 1:
    raise SystemExit(f"live detail team fragment count={detail.count(old_team)}")
detail = detail.replace(old_team, '${renderTeamEbookSection(m,te)}', 1)
s = s[:detail_start] + detail + s[detail_end:]

start = s.index("function openDetail(i,sync=true){")
end = s.index("\n$('#detailClose')", start)
new_open = r'''function openDetail(i,sync=true){const m=state.currentRun?.matches?.[i];if(!m)return;state.lastFocus=document.activeElement;state.openMatchKey=matchKey(m,i);$('#detailBody').innerHTML=detailHTML(m);const overlay=$('#detailOverlay');overlay.classList.add('open');overlay.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';overlay.focus();if(sync)syncURL();hydrateMatchSnapshot(m).then(()=>{if(state.openMatchKey===matchKey(m,i)&&$('#detailOverlay').classList.contains('open'))$('#detailBody').innerHTML=detailHTML(m)}).catch(e=>console.warn('Snapshot fallback failed',e))}'''
s = s[:start] + new_open + s[end:]

required = [
    "const snapshotDataCache=",
    "async function hydrateMatchSnapshot(m)",
    "function snapshotTeamBox(t,name,role)",
    "function renderSnapshotFabric(m)",
    "Team E-Books · Snapshot Fallback",
    "return renderSnapshotFabric(m)",
]
for marker in required:
    if marker not in s:
        raise SystemExit(f"missing marker: {marker}")

p.write_text(s, encoding="utf-8")
